import numpy as np,json,collections
a=np.array(G['Demo pair 1 input']); o=np.array(G['Demo pair 1 output'])
# check hypothesis: out = dominant color among non-5s; if a color's count in block >= its count of 5s in block -> that color else 0. Verify per-block on demo1, also tie-break, and on test.
def f(inp):
    a=np.array(inp); out=[]
    for i in range(0,a.shape[0]-2,3):
        row=[]
        for j in range(0,a.shape[1]-2,3):
            blk=a[i:i+3,j:j+3]
            c=collections.Counter(blk.flatten().tolist())
            c5=c[5]
            nz={v:c[v] for v in c if v!=5}
            if not nz:
                row.append(5 if c5>0 else 0)
            else:
                best=max(nz,key=nz.get)
                row.append(best if nz[best]>=c5 else 0)
        out.append(row)
    return out
print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])
res=f(G['Test input'])
for r in res: print(r)
print(json.dumps(res))
